mapper.select:
select
cpl.Cpl_Sort as cpdSort, cpl.Cpl_Parent_Id as cpdParentId, cpl.Cpl_Administration_Url as cpdAdministrationUrl, cpl.Cpl_Administration_Url_H as cpdAdministrationUrlH, cpl.Cpl_File_Expiain as cplFileExpiain, cpl.Cpl_Achievement_Type as cplAchievementType, dtl.* from Project_Cp_Dtl dtl left join Project_Cp cp on cp.Cp_Id=dtl.Cp_Id left join Pre_Project pro on pro.P_Id=cp.P_Id
left join Project_Cp_Library cpl on cpl.Cpl_Id=dtl.Cpd_Cpl_Id
and dtl.Cpd_Status = #{params.cpdStatus}
and dtl.Cp_Id = #{params.cpId}
and dtl.Te_Id = #{params.teId}
and pro.P_Id = #{params.pId}
and dtl.Cpd_State = 7
and dtl.Cpd_State != 7
and ( dtl.Cpd_State != 7 and dtl.Cpd_Plan_End_Time < now() )
order by dtl.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by dtl.Cpd_End_Time desc

select
cpl.Cpl_Sort as cpdSort, cpl.Cpl_Parent_Id as cpdParentId, cpl.Cpl_Administration_Url as cpdAdministrationUrl, cpl.Cpl_Administration_Url_H as cpdAdministrationUrlH, dtl.* from Project_Cp_Dtl dtl left join Project_Cp cp on cp.Cp_Id=dtl.Cp_Id left join Pre_Project pro on pro.P_Id=cp.P_Id
left join Project_Cp_Library cpl on cpl.Cpl_Id=dtl.Cpd_Cpl_Id
and dtl.Cpd_Status = #{params.cpdStatus}
and dtl.Cpd_Person_Id = #{params.cpdPersonId}
and dtl.Te_Id = #{params.teId}
and pro.P_Id = #{params.pId}
and dtl.Cpd_State = 7
and dtl.Cpd_State != 7
and ((dtl.Cpd_End_Time is null and dtl.Cpd_Plan_End_Time<now()) or (dtl.Cpd_End_Time is not null and dtl.Cpd_Plan_End_Time <= dtl.Cpd_End_Time) )
order by dtl.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by dtl.Cpd_End_Time desc

select

cp.P_Id as pId,
cpl.Cpl_Sort as cpdSort,
cpl.Cpl_Parent_Id as cpdParentId,
cpl.Cpl_Administration_Url as cpdAdministrationUrl,
cpl.Cpl_Administration_Url_H as cpdAdministrationUrlH,
dtl.*
from Project_Cp_Dtl dtl
left join Project_Cp cp on cp.Cp_Id=dtl.Cp_Id
left join Pre_Project pro on pro.P_Id=cp.P_Id

left join Project_Cp_Library cpl on cpl.Cpl_Id=dtl.Cpd_Cpl_Id
where dtl.Cpd_State=7 and dtl.Cpd_Status=1
and dtl.Cpd_End_Time is not null

    and dtl.Te_Id = #{params.teId}


    and pro.P_Type = #{params.pType}


    and pro.P_Region = #{params.pRegion}


    and pro.P_Project_Stage = #{params.pProjectStage}


    and pro.P_Construction_Unit = #{params.pConstructionUnit}


    and pro.P_Competent_Department = #{params.pCompetentDepartment}


    
        order by dtl.${params.sortFiled} ${params.sortType}
    
    
        order by ${params.sortSideFiled} ${params.sortType}
    
    
        order by dtl.Cpd_End_Time desc

select (select count(1) from ( (select distinct cpd.Cpd_Id from Project_Cp_Dtl cpd left join Project_Cp cp on cpd.CP_Id=cpd.CP_Id left join Pre_Project pro on cp.P_Id=pro.P_Id where cpd.Cpd_Status=1
) )a ) as cpDtlCount, (select count(1) from Project_Cp cp left join Pre_Project pro on cp.P_Id=pro.P_Id where 1=1
) as cpCount, (select count(1) from Project_Cp_Dtl where Cpd_State=7 and Cpd_Status=1
and Te_Id = #{params.teId} ) as completeCpDtlCount, (select count(1) from Pre_Project pro where 1=1
) as projectCount, (select count(1) from (select Cpd_Create_Uid from Project_Cp_Dtl cpd left join Project_Cp cp on cpd.CP_Id=cpd.CP_Id left join Pre_Project pro on cp.P_Id=pro.P_Id where cpd.Cpd_Status=1 and cpd.Cpd_Create_Uid is not null
group by Cpd_Create_Uid) a ) as cpDtlCreateUserCount

mapper.sql:
and pro.deleted=FALSE

    and pro.Te_Id = #{params.teId}


    and pro.P_Type = #{params.pType}


    and pro.P_Region = #{params.pRegion}


    and pro.State = #{params.state}


    and pro.P_Status = #{params.pStatus}


    and pro.P_Project_Stage = #{params.pProjectStage}


    and pro.P_Construction_Unit = #{params.pConstructionUnit}


    and pro.P_Competent_Department = #{params.pCompetentDepartment}


    and pro.P_Name like concat('%',#{params.pName},'%')

mapper.select:
select
cpl.Cpl_Sort as cpdSort, cpl.Cpl_Parent_Id as cpdParentId, cpl.Cpl_Administration_Url as cpdAdministrationUrl, cpl.Cpl_Administration_Url_H as cpdAdministrationUrlH, dtl.* from Project_Cp_Dtl dtl left join Project_Cp cp on cp.Cp_Id=dtl.Cp_Id left join Pre_Project pro on pro.P_Id=cp.P_Id
left join Project_Cp_Library cpl on cpl.Cpl_Id=dtl.Cpd_Cpl_Id where dtl.Cpd_Plan_End_Time is not null
and dtl.Te_Id = #{params.teId}
and pro.P_Name like concat('%',#{params.pName},'%')
and dtl.Cpd_Name like concat('%',#{params.cpdName},'%')
and dtl.Cpd_Person_Id=#{params.cpdPersonId}
and dtl.Cpd_Plan_End_Time <= #{params.temporaryTime}
and dtl.Cpd_State!=7
and cp.P_Id=#{params.pId}
order by dtl.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by dtl.Cpd_Plan_End_Time desc

select
(select count(1) from Project_Cp_Dtl cpd
left join Project_Cp cp on cp.Cp_Id=cpd.Cp_Id
left join Pre_Project pro on pro.P_Id=cp.P_Id
where cpd.Cpd_Status=1

    and cpd.Te_Id = #{params.teId}


    and pro.P_Type = #{params.pType}


    and pro.P_Region = #{params.pRegion}


    and pro.P_Project_Stage = #{params.pProjectStage}


    and pro.P_Construction_Unit = #{params.pConstructionUnit}


    and pro.P_Competent_Department = #{params.pCompetentDepartment}


    and cpd.Cpd_Plan_End_Time > #{params.startTime}


    and cpd.Cpd_Plan_End_Time < #{params.endTime}

) as "planComplete",
(select count(1) from Project_Cp_Dtl cpd
left join Project_Cp cp on cp.Cp_Id=cpd.Cp_Id
left join Pre_Project pro on pro.P_Id=cp.P_Id
where cpd.Cpd_Status=1

    and cpd.Te_Id = #{params.teId}


    and pro.P_Type = #{params.pType}


    and pro.P_Region = #{params.pRegion}


    and pro.P_Project_Stage = #{params.pProjectStage}


    and pro.P_Construction_Unit = #{params.pConstructionUnit}


    and pro.P_Competent_Department = #{params.pCompetentDepartment}


    and cpd.Cpd_State = #{params.cpdState}


    and cpd.Cpd_Plan_End_Time > #{params.startTime}


    and cpd.Cpd_Plan_End_Time < #{params.endTime}

) as "actualComplete"

select *  from  Project_Cp_Rpr mn

    ${authSql}


    where 1 = 1


    and  mn.Cpd_Id=#{cpdId}

select
pro.P_Name as pName,
cpd.*
from Project_Cp_Dtl cpd
left join Project_Cp cp on cp.CP_Id = cpd.CP_Id
left join Pre_Project pro on cp.P_Id = pro.P_Id
where cpd.Cpd_Status = 1

    and cpd.Cpd_State = #{params.cpdState}


    and cpd.Cpd_Plan_End_Time > #{params.startTime}


    and cpd.Cpd_Plan_End_Time < #{params.endTime}
